//! D3D11, DXGI and D3D compiler bindings, generated by `examples/generate_bindings.rs` with windows-bindgen.
//!
//! The same code runs on Windows and on Linux, where DXVK-native provides D3D11 and DXGI over Vulkan and vkd3d-utils provides
//! `D3DCompile` and `D3DReflect`. COM methods are `extern "system"`, which is the native ABI on Linux: the one DXVK-native and
//! the patched vkd3d build use.

#[allow(non_snake_case, non_camel_case_types, non_upper_case_globals, dead_code, clippy::all)]
mod bindings;

pub use bindings::*;

/// Prepares the platform for the first D3D11 call. On Linux, tells DXVK-native to use SDL3 for windows, and to log to stderr
/// only instead of writing `<exe>_d3d11.log` files into the working directory, unless `DXVK_WSI_DRIVER` / `DXVK_LOG_PATH` say otherwise.
///
/// # Safety
///
/// Call it before other threads exist: it may set environment variables.
pub unsafe fn init_platform() {
    if !cfg!(target_os = "linux") {
        return;
    }

    for (name, value) in [("DXVK_WSI_DRIVER", "SDL3"), ("DXVK_LOG_PATH", "none")] {
        if std::env::var_os(name).is_none() {
            // SAFETY: the caller guarantees no other thread reads the environment meanwhile.
            unsafe { std::env::set_var(name, value) };
        }
    }
}
